DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260108182115_AddPersonnelRequest') THEN
    CREATE TABLE "PersonnelRequests" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "EvaluationId" integer NOT NULL,
        "CustomerId" integer NOT NULL,
        "CustomerOrganizationId" integer NOT NULL,
        "FirstName" text NOT NULL,
        "LastName" text NOT NULL,
        "Title" text,
        "Notes" text,
        "RequestedByUserId" integer NOT NULL,
        "Status" integer NOT NULL,
        "ReviewedByUserId" integer,
        "ReviewedAt" timestamp with time zone,
        "RejectReason" text,
        "CreatedPersonnelId" integer,
        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone,
        "CreatedBy" text,
        "UpdatedBy" text,
        "IsDeleted" boolean NOT NULL,
        CONSTRAINT "PK_PersonnelRequests" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_PersonnelRequests_CustomerOrganizations_CustomerOrganizatio~" FOREIGN KEY ("CustomerOrganizationId") REFERENCES "CustomerOrganizations" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_PersonnelRequests_CustomerPersonnel_CreatedPersonnelId" FOREIGN KEY ("CreatedPersonnelId") REFERENCES "CustomerPersonnel" ("Id") ON DELETE SET NULL,
        CONSTRAINT "FK_PersonnelRequests_Customers_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "Customers" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_PersonnelRequests_Evaluations_EvaluationId" FOREIGN KEY ("EvaluationId") REFERENCES "Evaluations" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_PersonnelRequests_Users_RequestedByUserId" FOREIGN KEY ("RequestedByUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_PersonnelRequests_Users_ReviewedByUserId" FOREIGN KEY ("ReviewedByUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
    );
